const CSS=`
@import url('https://fonts.googleapis.com/css2?family=DM+Sans:wght@300;400;500;600;700;800;900&family=Playfair+Display:wght@400;600;700;800&display=swap');
:root{--bg:#fff;--bg2:#F5F7FA;--txt:#1A1F36;--txt2:#5A6178;--txt3:#8E94A8;--acc:#253B80;--acc2:#3A5BC7;--tc:#FFC72C;--tcD:#E8A800;--brd:#E2E6EE;--sh:0 2px 12px rgba(37,59,128,.06);--blt:#EEF1F8}
*{margin:0;padding:0;box-sizing:border-box}
body{background:var(--bg2)}
@keyframes fadeUp{from{opacity:0;transform:translateY(20px)}to{opacity:1;transform:translateY(0)}}
@keyframes cardIn{from{opacity:0;transform:translateY(10px) scale(.98)}to{opacity:1;transform:translateY(0) scale(1)}}
@keyframes gradShift{0%{background-position:0% 50%}50%{background-position:100% 50%}100%{background-position:0% 50%}}
@keyframes glow{0%,100%{box-shadow:0 2px 16px rgba(37,59,128,.06)}50%{box-shadow:0 4px 28px rgba(37,59,128,.13)}}
@keyframes bannerCycle{0%{opacity:0;transform:translateY(-100%)}8%{opacity:1;transform:translateY(0)}92%{opacity:1}100%{opacity:0;transform:translateY(100%)}}
@keyframes splashZoom{0%{transform:scale(1.3);opacity:0}20%{transform:scale(1);opacity:1}80%{transform:scale(1);opacity:1}100%{transform:scale(1.05);opacity:0}}
@keyframes splashBg{0%{opacity:1}80%{opacity:1}100%{opacity:0}}
@keyframes splashTxt{0%{opacity:0;transform:translateY(30px)}30%{opacity:1;transform:translateY(0)}80%{opacity:1}100%{opacity:0;transform:translateY(-20px)}}
@keyframes wave{0%{transform:translateX(0)}100%{transform:translateX(-50%)}}
@keyframes pulse5g{0%,100%{box-shadow:0 0 0 0 rgba(13,124,61,.3)}50%{box-shadow:0 0 0 6px rgba(13,124,61,0)}}
@keyframes waveChar{0%,100%{transform:translateY(0);color:#fff}25%{transform:translateY(-6px);color:#FFC72C}50%{transform:translateY(0);color:#fff}}
@keyframes countPulse{0%,100%{transform:scale(1)}50%{transform:scale(1.06)}}
@keyframes shimmerBg{0%{background-position:-200% center}100%{background-position:200% center}}
.au{animation:fadeUp .5s ease-out forwards}.ac{animation:cardIn .4s ease-out forwards}
.back-fab{position:fixed;bottom:90px;right:20px;z-index:90;width:44px;height:44px;border-radius:50%;background:var(--acc);color:#fff;border:none;font-size:18px;cursor:pointer;box-shadow:0 4px 16px rgba(37,59,128,.3);display:flex;align-items:center;justify-content:center;transition:all .2s;font-family:inherit}
.back-fab:hover{transform:scale(1.1);box-shadow:0 6px 24px rgba(37,59,128,.4)}
.back-fab:active{transform:scale(.95)}
@keyframes chatSlideUp{from{opacity:0;transform:translateY(20px) scale(.95)}to{opacity:1;transform:translateY(0) scale(1)}}
@keyframes chatDot{0%,80%,100%{transform:scale(0)}40%{transform:scale(1)}}
.chat-panel{animation:chatSlideUp .3s ease-out forwards}
::-webkit-scrollbar{width:5px}::-webkit-scrollbar-track{background:var(--bg2)}::-webkit-scrollbar-thumb{background:#ccc;border-radius:3px}
input[type=range]{-webkit-appearance:none;width:100%;height:5px;background:linear-gradient(90deg,var(--acc),var(--tc));border-radius:3px;outline:none;cursor:pointer}
input[type=range]::-webkit-slider-thumb{-webkit-appearance:none;width:20px;height:20px;border-radius:50%;background:#fff;border:3px solid var(--acc);cursor:pointer;box-shadow:0 2px 6px rgba(0,0,0,.15)}
@media(max-width:768px){.desk-nav{display:none!important}.hamburger{display:flex!important}.hero-title{font-size:26px!important}.stat-grid{grid-template-columns:repeat(3,1fr)!important}.grid-cards{grid-template-columns:1fr!important}}
@media(max-width:480px){.stat-grid{grid-template-columns:repeat(2,1fr)!important}.hero-btns{flex-direction:column!important}.hero-btns button,.hero-btns a{width:100%!important}.detail-grid{grid-template-columns:1fr 1fr!important}}
`;

